-- 005: starter content. Edit later from the admin dashboard.
-- Run 002 first (it creates short_description). For an existing database, 006 updates the services.
-- No fake projects, reviews or statistics.

on conflict (slug) do update set title=excluded.title, icon=excluded.icon, description=excluded.description,
  short_description=excluded.short_description, benefits=excluded.benefits, sort_order=excluded.sort_order;

on conflict (key) do update set value = excluded.value, is_public = excluded.is_public;
