('about', $j${"background": "DE DON DC Facility Management And Cleaning Services is a Nigerian company established in November 2022, providing professional cleaning, fumigation, pest control and facility maintenance solutions for residential, commercial, hospitality, healthcare, educational and industrial environments.\n\nLed by a professional with previous cleaning and facilities-related experience in the United Arab Emirates (UAE), we are committed to delivering dependable services through appropriate cleaning methods, attention to detail, responsible chemical handling and professional customer service.", "mission": "To deliver dependable, quality-focused cleaning and facility management solutions that promote cleanliness, hygiene, safety and comfort for our clients.", "vision": "To become a trusted cleaning and facility management service provider recognised for professionalism, reliability, customer satisfaction and consistent service quality in Nigeria and international markets.", "values": [{"title": "Professionalism", "text": "We approach every assignment with respect, discipline and attention to agreed requirements."}, {"title": "Integrity", "text": "We aim to communicate honestly, provide clear quotations and deliver services according to agreed terms."}, {"title": "Quality", "text": "We focus on careful workmanship and suitable cleaning methods."}, {"title": "Safety", "text": "We promote responsible chemical handling, appropriate protective equipment and safe working procedures."}, {"title": "Customer satisfaction", "text": "We listen to our clients and aim to meet their expectations through clear communication and service accountability."}, {"title": "Continuous improvement", "text": "We value training, practical experience and opportunities to improve our methods and service delivery."}], "experience": {"intro": "Our founder gained practical cleaning and facilities-related experience through previous employment in the UAE. This gave valuable exposure to cleaning operations across healthcare, hospitality, pharmaceutical, educational and construction-related environments.", "employers": [{"name": "Ammar Facilities Management and Contracting LLC, UAE", "period": "October 2013 – January 2016"}, {"name": "Fajr Al Sharq Construction LLC, UAE", "period": "June 2016 – August 2018"}], "exposure_title": "Assignments and industry exposure during employment with Ammar included:", "exposure": ["Sheikh Khalifa Medical City Ajman (SKMCA), UAE", "Hot Oven LLC, Sharjah, UAE", "International School of Creative Science, Sharjah, UAE", "American School of Creative Science, Sharjah, UAE", "Gulf Pharmaceutical Industries (JULPHAR), Al Digdaga, Ras Al Khaimah, UAE", "Crown Palace Hotel, Ajman, UAE", "American School of Creative Science, Dubai, UAE"]}, "commitment": "We aim to maintain clean, hygienic, safe and presentable environments through reliable service delivery and professional attention to detail. We welcome opportunities to work with hotels, serviced apartments, corporate offices, schools, healthcare facilities, construction companies, residential clients and other organisations seeking dependable cleaning and facility support services."}$j$::jsonb, true),
